// The product's name and contact (design/tokens.json brand) as each client's constants, so a
// client reads its user-facing name from one generated source rather than typing it.

import { brand } from './tokens.mjs';
import { xamlHeader } from './emit-xaml.mjs';
import { header } from './emit-pwa.mjs';

const DOC = 'docs/design/brand.md, The name';

export function brandFiles(tokens) {
  const b = brand(tokens);
  const swiftHeader = `// ${header('design/tokens.json (brand)').replace(/\n\s*/g, ' ')}`;
  return {
    'src/AgentBridge.Protocol/DesignBrand.cs': `// <auto-generated>
// ${xamlHeader('design/tokens.json (brand)').replace(/\n\s*/g, ' ')}
// </auto-generated>

namespace AgentBridge.Protocol;

// The product's user-facing name and contact (${DOC}), beside Product: for the
// Windows app, the host and AgentBridge.Local, and linked into the host launcher as Product is.
// Identifiers, paths, package IDs and protocol names are not the brand, and don't come from here.
public static class DesignBrand
{
    public const string Name = "${b.name}";
    public const string ShortName = "${b.shortName}";
    public const string SupportEmail = "${b.supportEmail}";
}
`,
    'pwa/design/brand.js': `/* ${header('design/tokens.json (brand)')} */

// The product's user-facing name and contact (${DOC}).
export const BRAND = Object.freeze({
  name: '${b.name}',
  shortName: '${b.shortName}',
  supportEmail: '${b.supportEmail}',
});
`,
    'design/apple/Brand.swift': `${swiftHeader}

// The product's user-facing name and contact (${DOC}).
public enum Brand {
    public static let name = "${b.name}"
    public static let shortName = "${b.shortName}"
    public static let supportEmail = "${b.supportEmail}"
}
`,
    'design/android/values/brand.xml': `<?xml version="1.0" encoding="utf-8"?>
<!-- ${header('design/tokens.json (brand)')} -->
<resources>
    <string name="brand_name" translatable="false">${b.name}</string>
    <string name="brand_short_name" translatable="false">${b.shortName}</string>
    <string name="brand_support_email" translatable="false">${b.supportEmail}</string>
</resources>
`,
  };
}

